00198 //-------------------------------------------------------------------- FUNCTIONS
00199 
00200 /*
00201 
00202   Returns the WinBinder code that results from the resource text $rc, usually
00203    read from a RC (Windows resource) file.
00204 
00205 TODO: Extend support to several RC generators (currently supports WinAsm Studio only)
00206 NOTE: Caption is not used, it's taken from the resource instead. The parameter is kept
00207       here just to be compatible with wb_create_window()
00208 */
00209 
00210 function parse_rc(
00211     $rc,
00212     $winvar = '$mainwin',
00213     $parent = 0,
00214     $type = "AppWindow",
00215     $caption = "",
00216     $x = WBC_CENTER,
00217     $y = WBC_CENTER,
00218     $width = WBC_CENTER,
00219     $height = WBC_CENTER,
00220     $style = 0,
00221     $lparam = 0,
00222     $respath = PATH_RES
00223 ) {
00224     global $_winclass, $_usergeom, $path_res;
00225 
00226     // Read file
00227 
00228     $_usergeom = array($x, $y, $width, $height);
00229     $path_res  = $respath;
00230 
00231     // Remove comments and useless spaces
00232 
00233     $rc = preg_replace("/^\s*;.*$/m", "", $rc);
00234     $rc = preg_replace("/^\s*(.*)$/m", "\\1", $rc);
00235 
00236     // Maintain #defines and discard the rest (fixed to work with newer versions of PHP -- thanks Hans)
00237 
00238 //  $def = preg_replace("/(?!^\s*#define)(.*)$/m", "\\2", $rc);
00239     $def = preg_replace('/^((?!#define).)*$/m', "\\2", $rc);
00240 
00241     // Remove blank lines
00242 
00243     $def = preg_replace("/\n+/m", "\n", $def);
00244 
00245     // Change string C #defines to PHP format
00246 
00247     $def = preg_replace("/#define\s+(\w+)\s+\"(.*)\"/", "if(!defined(\"\\1\")) define(\"\\1\", \"\\2\");", $def);
00248 
00249     // Change character C #defines to PHP format
00250 
00251     $def = preg_replace("/#define\s+(\w+)\s+'(.+)'/", "if(!defined(\"\\1\")) define(\"\\1\", \"\\2\");", $def);
00252 
00253     // Change numeric C #defines to PHP format
00254 
00255     $def = preg_replace("/#define\s+(\w+)\s+(\S+)/", "if(!defined(\"\\1\")) define(\"\\1\", \\2);", $def);
00256     $def = "// Control identifiers\n\n" . preg_replace("/(\r\n|\r|\n)+/sm", "\n", $def);
00257 
00258     // Return to original string and eliminates the #defines
00259 
00260     $rc = preg_replace("/^\s*#define(.*)$/m", "", $rc);
00261 
00262     // Create the window
00263 
00264     $_winclass = $type;
00265 
00266     $tok = "\s*((?:[\"'][\S \t]*[\"'])|(?:[\S^,'\"]+))\s*";    // Normal or quoted token
00267     $rc  = "// Create window\n\n" . preg_replace_callback("/^$tok\s+DIALOGEX$tok,$tok,$tok,$tok\s+CAPTION$tok\s+FONT$tok,$tok\s+STYLE$tok\s+EXSTYLE$tok/m", "_scale_dialog", $rc);
00268 
00269     // Create the controls
00270 
00271     $rc = preg_replace_callback("/^\s*CONTROL\s+$tok,$tok,$tok,$tok,$tok,$tok,$tok,$tok,$tok/m", "_scale_controls", $rc);
00272 
00273     // Create BEGIN / END comments
00274 
00275     $rc = preg_replace("/^\s*BEGIN/m", "\n// Insert controls\n", $rc);
00276     $rc = preg_replace("/^\s*END/m", "\n// End controls", $rc);
00277 
00278     // Replace variable names
00279 
00280     $rc = str_replace("%WINVAR%", $winvar, $rc);
00281     $rc = str_replace("%PARENT%", $parent ? $parent : "0", $rc);
00282     $rc = str_replace("%STYLE%", $style, $rc);
00283     $rc = str_replace("%LPARAM%", $lparam, $rc);
00284 
00285     return "$def\n$rc";
00286 }
00287 
00288 //----------------------------------------------------------- INTERNAL FUNCTIONS
00289 
00290 function _scale_dialog($c)
00291 {
00292     global $_winclass, $_usergeom, $_tabN;
00293 
00294     if ($_winclass == "TabControl") {
00295         $_tabN++;
00296         $code = "wb_create_item(%PARENT%, " . $c[6] . ");\n";
00297     } else {
00298         $_addx = 8;                    //width + 2xborder
00299         $_addy = 4 + 42 + 17 + 4;    //border + caption + border
00300 
00301         switch (is_string($_winclass) ? strtolower($_winclass) : $_winclass) {
00302             case "appwindow":
00303                 $_winclass = AppWindow;
00304                 $_addx     = 8;                    //width + 2xborder
00305                 $_addy     = 3 + 18 + 22 + 18 + 3;    //border + caption + menu + statusbar + border
00306                 break;
00307             case "resizablewindow":
00308                 $_winclass = ResizableWindow;
00309                 $_addx     = 8;                    //width + 2xborder
00310                 $_addy     = 4 + 42 + 17 + 4;    //border + caption + menu + statusbar + border
00311                 break;
00312             case "modaldialog":
00313                 $_winclass = ModalDialog;
00314                 $_addx     = 8;                    //width + 2xborder
00315                 $_addy     = 4 + 42 + 17 + 4;    //border + caption + border
00316                 break;
00317             case "modelessdialog":
00318                 $_winclass = ModelessDialog;
00319                 break;
00320             case "tooldialog":
00321                 $_winclass = ToolDialog;
00322                 break;
00323         }
00324 
00325         if (!(($_usergeom[0] == WBC_CENTER && $_usergeom[1] == WBC_CENTER &&
00326             $_usergeom[2] == WBC_CENTER && $_usergeom[3] == WBC_CENTER))) {
00327             $code = "%WINVAR% = wb_create_window(" .
00328                 "%PARENT%, " .                                // parent
00329                 "$_winclass, " .                            // class
00330                 $c[6] . ", " .                                // caption
00331                 $_usergeom[0] . ", " .                        // left
00332                 $_usergeom[1] . ", " .                        // top
00333                 $_usergeom[2] . ", " .                        // width
00334                 $_usergeom[3] . ", " .                        // height
00335                 "%STYLE%, " .                                // style
00336                 "%LPARAM%);\n";                                // lparam
00337 
00338         } else {
00339             if (is_array($_usergeom)) {
00340                 if (count($_usergeom) == 2) {        // Width, height only
00341                     $_usergeom[2] = $_usergeom[0];
00342                     $_usergeom[3] = $_usergeom[1];
00343                     $_usergeom[0] = WBC_CENTER;
00344                     $_usergeom[1] = WBC_CENTER;
00345                 }
00346             } elseif (is_null($_usergeom)) {
00347                 $_usergeom[0] = WBC_DEFAULTPOS;
00348                 $_usergeom[1] = WBC_DEFAULTPOS;
00349                 $_usergeom[2] = WBC_DEFAULTPOS;
00350                 $_usergeom[3] = WBC_DEFAULTPOS;
00351             }
00352 
00353             $code = "%WINVAR% = wb_create_window(" .
00354                 "%PARENT%, " .                                // parent
00355                 "$_winclass, " .                            // class
00356                 $c[6] . ", " .                                // caption
00357                 "WBC_CENTER, " .                            // left
00358                 "WBC_CENTER, " .                            // top
00359 //          (int)($c[4] * WB_KX_SCREEN + $_addx) . ", " .
00360 //          (int)($c[5] * WB_KY_SCREEN + $_addy) . ", " .
00361                 (int)($c[4] * WB_KX_SCREEN) . ", " .
00362                 (int)($c[5] * WB_KY_SCREEN) . ", " .
00363                 "%STYLE%, " .                                // style
00364                 "%LPARAM%);\n";                                // lparam
00365         }
00366 
00367         $_tabN = 0;
00368     }
00369 
00370     return $code;
00371 }
00372 
00373 function _scale_controls($c)
00374 {
00375     global $_tabN, $path_res;
00376 
00377     $winclass   = $c[3];
00378     $winstyle   = hexdec($c[4]);
00379     $winexstyle = hexdec($c[9]);
00380 
00381     if (_bit_test($winstyle, WS_VISIBLE)) {
00382         $style = "WBC_VISIBLE";
00383     } else {
00384         $style = "WBC_INVISIBLE";
00385     }
00386 
00387     if (_bit_test($winstyle, WS_DISABLED)) {
00388         $style .= " | WBC_DISABLED";
00389     } else {
00390         $style .= " | WBC_ENABLED";
00391     }
00392 
00393     if (_bit_test($winexstyle, WS_EX_STATICEDGE)) {
00394         $style .= " | WBC_BORDER";
00395     }
00396 
00397     // Set attributes according to control class
00398 
00399     switch (strtolower($winclass)) {
00400         case '"button"':
00401 
00402             switch ($winstyle & 0x0F) {
00403                 case BS_AUTORADIOBUTTON:
00404                 case BS_RADIOBUTTON:
00405                     $class = "RadioButton";
00406                     if (_bit_test($winstyle, WS_GROUP)) {
00407                         $style .= " | WBC_GROUP";
00408                     }
00409                     break;
00410                 case BS_AUTOCHECKBOX:
00411                 case BS_CHECKBOX:
00412                     $class = "CheckBox";
00413                     break;
00414                 case BS_GROUPBOX:
00415                     $class = "Frame";
00416                     break;
00417                 case BS_PUSHBUTTON:
00418                 default:
00419                     $class = "PushButton";
00420                     break;
00421             }
00422             break;
00423 
00424         case '"static"':
00425 
00426             switch ($winstyle & 0x1F) {
00427                 case SS_ICON:
00428                 case SS_BITMAP:
00429                     $style .= " | WBC_IMAGE | WBC_CENTER";
00430                     $class = "Frame";
00431                     break;
00432                 case SS_ETCHEDHORZ:
00433                 case SS_ETCHEDVERT:
00434                 case SS_ETCHEDFRAME:
00435                     $class = "Frame";
00436                     break;
00437                 case SS_CENTER:
00438                     if (_bit_test($winstyle, SS_WORDELLIPSIS)) {
00439                         $style .= " | WBC_ELLIPSIS";
00440                     }
00441                     $style .= " | WBC_CENTER";
00442                     $class = "Label";
00443                     break;
00444                 case SS_RIGHT:
00445                     if (_bit_test($winstyle, SS_WORDELLIPSIS)) {
00446                         $style .= " | WBC_ELLIPSIS";
00447                     }
00448                     $style .= " | WBC_RIGHT";
00449                     $class = "Label";
00450                     break;
00451                 case SS_LEFT:
00452                 default:
00453                     if (!_bit_test($winstyle, SS_LEFTNOWORDWRAP)) {
00454                         $style .= " | WBC_MULTILINE";
00455                     }
00456                     if (_bit_test($winstyle, SS_WORDELLIPSIS)) {
00457                         $style .= " | WBC_ELLIPSIS";
00458                     }
00459                     $class = "Label";
00460                     break;
00461             }
00462             break;
00463 
00464         case '"edit"':
00465             $class = "EditBox";
00466             if (_bit_test($winstyle, ES_MULTILINE)) {
00467                 $style .= " | WBC_MULTILINE";
00468             } else {
00469                 switch ($winstyle & 0x03) {
00470                     case ES_CENTER:
00471                         $style .= " | WBC_CENTER";
00472                         break;
00473                     case ES_RIGHT:
00474                         $style .= " | WBC_RIGHT";
00475                         break;
00476                     case ES_LEFT:
00477                     default:
00478                         break;
00479                 }
00480             }
00481             if (_bit_test($winstyle, ES_READONLY)) {
00482                 $style .= " | WBC_READONLY";
00483             }
00484             if (_bit_test($winstyle, ES_PASSWORD)) {
00485                 $style .= " | WBC_MASKED";
00486             }
00487             if (_bit_test($winstyle, ES_NUMBER)) {
00488                 $style .= " | WBC_NUMBER";
00489             }
00490             break;
00491 
00492         case '"richedit20a"':
00493             if (_bit_test($winstyle, ES_READONLY)) {
00494                 $style .= " | WBC_READONLY";
00495             }
00496             $class = "RTFEditBox";
00497             switch ($winstyle & 0x03) {
00498                 case ES_CENTER:
00499                     $style .= " | WBC_CENTER";
00500                     break;
00501                 case ES_RIGHT:
00502                     $style .= " | WBC_RIGHT";
00503                     break;
00504                 case ES_LEFT:
00505                 default:
00506                     break;
00507             }
00508             break;
00509 
00510         case '"combobox"':
00511             $class = "ComboBox";
00512             if (_bit_test($winstyle, CBS_SORT)) {
00513                 $style .= " | WBC_SORT";
00514             }
00515             if (_bit_test($winstyle, CBS_DROPDOWNLIST)) {
00516                 $style .= " | WBC_READONLY";
00517             }
00518             break;
00519 
00520         case '"listbox"':
00521             $class = "ListBox";
00522             if (_bit_test($winstyle, LBS_SORT)) {
00523                 $style .= " | WBC_SORT";
00524             }
00525             break;
00526 
00527         case '"scrollbar"':
00528             $class = "ScrollBar";
00529             break;
00530 
00531         case '"syslistview32"':
00532             $class = "ListView";
00533             if (!_bit_test($winstyle, LVS_NOSORTHEADER)) {
00534                 $style .= " | WBC_SORT";
00535             }
00536             if (_bit_test($winstyle, LVS_GRIDLINES)) {
00537                 $style .= " | WBC_LINES";
00538             }
00539             if (_bit_test($winstyle, LVS_CHECKBOXES)) {
00540                 $style .= " | WBC_CHECKBOXES";
00541             }
00542             if (!_bit_test($winstyle, LVS_SINGLESEL)) {
00543                 $style .= " | WBC_SINGLE";
00544             }
00545             break;
00546 
00547         case '"systabcontrol32"':
00548             $class = "TabControl";
00549             break;
00550 
00551         case '"systreeview32"':
00552             $class = "TreeView";
00553             break;
00554 
00555         case '"toolbarwindow32"':
00556             $class = "ToolBar";
00557             break;
00558 
00559         case '"msctls_progress32"':
00560             $class = "Gauge";
00561             break;
00562 
00563         case '"msctls_statusbar32"':
00564             $class = "StatusBar";
00565             break;
00566 
00567         case '"sysmonthcal32"':
00568             $class = "Calendar";
00569             break;
00570 
00571         case '"msctls_trackbar32"':
00572             $class = "Slider";
00573             if (_bit_test($winstyle, TBS_AUTOTICKS)) {
00574                 $style .= " | WBC_LINES";
00575             }
00576             break;
00577 
00578         case '"msctls_updown32"':
00579             $class = "Spinner";
00580             if (_bit_test($winstyle, WS_GROUP)) {
00581                 $style .= " | WBC_GROUP";
00582             }
00583             break;
00584     }
00585 
00586     // Convert Windows style to WinBinder style
00587 
00588     $str = "wb_create_control(" .
00589         "%WINVAR%, " .                                // Parent
00590         $class . ", " .                            // Class
00591         $c[1] . ", " .                                // Caption
00592         (int)($c[5] * WB_KX_SCREEN) . ", " .        // Left
00593         (int)($c[6] * WB_KY_SCREEN) . ", " .        // Top
00594         (int)($c[7] * WB_KX_SCREEN) . ", " .        // Width
00595         (int)($c[8] * WB_KY_SCREEN) . ", " .        // Height
00596         $c[2] . ", " .                                // ID
00597         $style . ", " .                                // Style
00598         "0" .                                        // Param
00599         ($_tabN ? ", " . ($_tabN - 1) . ");\n" : ");\n");    // Tab #
00600 
00601     // Add some attributes to controls where needed
00602 
00603     switch ($class) {
00604         case "Frame":
00605 
00606             if (strstr($style, "WBC_IMAGE")) {
00607                 if (($winstyle & (SS_BITMAP | SS_ICON)) && ($c[1] !== '""')) {
00608                     $image = $path_res . _trim_quotes($c[1]);
00609                     if (preg_match("/\.(bmp|ico)$/", $image)) {
00610                         $str = "\$_tmp_ctrl_ = " . $str . "wb_set_image(\$_tmp_ctrl_, '$image', GREEN);" . " unset(\$_tmp_ctrl_);\n";
00611                     }
00612                 }
00613             }
00614             break;
00615 
00616         case "PushButton":
00617 
00618             if (($winstyle & (BS_BITMAP | BS_ICON)) && ($c[1] !== '""')) {
00619                 $image = $path_res . _trim_quotes($c[1]);
00620                 if ($image) {
00621                     if (preg_match("/\.(bmp|ico)$/", $image)) {
00622                         $str = "\$_tmp_ctrl_ = " . $str . "wb_set_image(\$_tmp_ctrl_, '$image', GREEN);" . " unset(\$_tmp_ctrl_);\n";
00623                     }
00624                 }
00625             }
00626             break;
00627     }
00628 
00629     return $str;
00630 }
00631 
00632 function _trim_quotes($str)
00633 {
00634     return str_replace('"', '', $str);
00635 }
00636 
00637 function _bit_test($v, $t)
00638 {
